import { supabaseAdmin } from "../_shared/supabase-admin.ts";
import { loadDriverOnboardingSnapshot } from "../_shared/driver-onboarding.ts";
import { getRequestDriverContext } from "../_shared/request-profile.ts";
import { internalError, jsonResponse, methodNotAllowed, preflightResponse } from "../_shared/responses.ts";

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") {
    return preflightResponse();
  }

  if (request.method !== "GET") {
    return methodNotAllowed();
  }

  try {
    const driver = await getRequestDriverContext(request);
    if (!driver) {
      return jsonResponse({ error: "Unauthorized" }, 401);
    }

    const snapshot = await loadDriverOnboardingSnapshot(driver.userId);
    const { data: notifications, error: notificationError } = await supabaseAdmin.schema("public")
      .from("notifications").select("id,type,message,payload,read,created_at")
      .eq("user_id", driver.userId).like("type", "SARCA_KYC_%")
      .order("created_at", { ascending: false }).limit(20);
    if (notificationError) console.error("sarca-kyc-notifications-read-failed", notificationError.code);
    const profile = snapshot.driverProfile;
    const review = {
      status: profile.status === "pending" && profile.rejection_reason && profile.onboarding_reviewed_at ? "correction_requested" : profile.status,
      message: profile.rejection_reason || (profile.status === "active" ? "O seu perfil foi aprovado." : null),
      reviewed_at: profile.onboarding_reviewed_at || null,
    };
    return jsonResponse({ ...snapshot, review, notifications: notifications || [] }, 200, { "Cache-Control": "private, no-store, max-age=0" });
  } catch (error) {
    console.error("get-driver-onboarding failed", error);
    return internalError("Failed to load driver onboarding.");
  }
});

import { supabaseAdmin } from "./supabase-admin.ts";
import { loadDriverDigitalPaymentPolicy } from "./driver-digital-policy.ts";

export const REQUIRED_DRIVER_DOCUMENT_TYPES = [
  "bi_front",
  "bi_back",
  "selfie",
  "driver_license",
  "vehicle_registration",
  "vehicle_front",
  "vehicle_back",
  "vehicle_side",
  "vehicle_interior",
  "vehicle_with_driver",
] as const;

export type DriverDocumentType = typeof REQUIRED_DRIVER_DOCUMENT_TYPES[number];

export type DriverOnboardingSnapshot = {
  ok: true;
  profile: Record<string, unknown>;
  driverProfile: Record<string, unknown>;
  vehicle: Record<string, unknown> | null;
  documents: Array<Record<string, unknown>>;
  digitalPaymentPolicy: Record<string, unknown>;
  checklist: {
    requiredCount: number;
    completedCount: number;
    progressPercent: number;
    missingRequirements: string[];
    canSubmit: boolean;
  };
};

export async function loadDriverOnboardingSnapshot(userId: string): Promise<DriverOnboardingSnapshot> {
  let { data: profile, error: profileError } = await supabaseAdmin
    .schema("public")
    .from("profiles")
    .select("id, user_id, role, phone, full_name, avatar_url")
    .eq("user_id", userId)
    .maybeSingle();

  if (!profile && !profileError) {
    const fallback = await supabaseAdmin
      .schema("public")
      .from("profiles")
      .select("id, user_id, role, phone, full_name, avatar_url")
      .eq("id", userId)
      .maybeSingle();
    profile = fallback.data;
    profileError = fallback.error;
  }

  if (profileError || !profile) {
    throw profileError;
  }

  const { data: driverProfile, error: driverProfileError } = await supabaseAdmin
    .schema("sarca")
    .from("driver_profiles")
    .select(`
      user_id,
      status,
      commission_rate,
      personal_id_number,
      licence_number,
      onboarding_completed,
      onboarding_submitted_at,
      onboarding_reviewed_at,
      rejection_reason,
      terms_accepted_at,
      is_online,
      current_lat,
      current_lng,
      rating,
      total_trips,
      created_at,
      updated_at
    `)
    .eq("user_id", userId)
    .single();

  if (driverProfileError || !driverProfile) {
    throw driverProfileError;
  }

  const { data: vehicles, error: vehiclesError } = await supabaseAdmin
    .schema("sarca")
    .from("vehicles")
    .select(`
      id,
      driver_user_id,
      vehicle_type,
      service_class,
      make,
      model,
      color,
      plate_number,
      year,
      has_air_conditioning,
      photo_url,
      is_active,
      created_at,
      updated_at
    `)
    .eq("driver_user_id", userId)
    .order("updated_at", { ascending: false })
    .limit(1);

  if (vehiclesError) {
    throw vehiclesError;
  }

  const { data: documents, error: documentsError } = await supabaseAdmin
    .schema("sarca")
    .from("driver_documents")
    .select(`
      id,
      driver_user_id,
      document_type,
      file_path,
      status,
      rejection_reason,
      reviewed_by_user_id,
      reviewed_at,
      created_at,
      updated_at
    `)
    .eq("driver_user_id", userId)
    .order("document_type", { ascending: true });

  if (documentsError) {
    throw documentsError;
  }

  const digitalPaymentPolicy = await loadDriverDigitalPaymentPolicy(userId);

  return buildDriverOnboardingSnapshot({
    profile,
    driverProfile,
    vehicle: vehicles?.[0] ?? null,
    documents: documents ?? [],
    digitalPaymentPolicy,
  });
}

export function buildDriverOnboardingSnapshot({
  profile,
  driverProfile,
  vehicle,
  documents,
  digitalPaymentPolicy,
}: {
  profile: Record<string, unknown>;
  driverProfile: Record<string, unknown>;
  vehicle: Record<string, unknown> | null;
  documents: Array<Record<string, unknown>>;
  digitalPaymentPolicy: Record<string, unknown>;
}): DriverOnboardingSnapshot {
  const missingRequirements: string[] = [];
  let completedCount = 0;

  if (typeof profile.full_name === "string" && profile.full_name.trim().length > 0) {
    completedCount += 1;
  } else {
    missingRequirements.push("Nome completo");
  }

  if (typeof driverProfile.personal_id_number === "string" && driverProfile.personal_id_number.trim().length > 0) {
    completedCount += 1;
  } else {
    missingRequirements.push("Numero do BI");
  }

  if (typeof driverProfile.licence_number === "string" && driverProfile.licence_number.trim().length > 0) {
    completedCount += 1;
  } else {
    missingRequirements.push("Numero da carta de conducao");
  }

  if (driverProfile.terms_accepted_at) {
    completedCount += 1;
  } else {
    missingRequirements.push("Aceitar termos e condicoes");
  }

  const vehicleChecks = [
    { label: "Tipo de veiculo", ok: typeof vehicle?.vehicle_type === "string" && vehicle.vehicle_type.trim().length > 0 },
    { label: "Marca do veiculo", ok: typeof vehicle?.make === "string" && vehicle.make.trim().length > 0 },
    { label: "Modelo do veiculo", ok: typeof vehicle?.model === "string" && vehicle.model.trim().length > 0 },
    { label: "Matricula do veiculo", ok: typeof vehicle?.plate_number === "string" && vehicle.plate_number.trim().length > 0 },
    { label: "Ano do veiculo", ok: Number.isFinite(Number(vehicle?.year ?? null)) && Number(vehicle?.year ?? 0) > 0 },
    { label: "Categoria do servico", ok: typeof vehicle?.service_class === "string" && vehicle.service_class.trim().length > 0 },
  ];

  for (const check of vehicleChecks) {
    if (check.ok) {
      completedCount += 1;
    } else {
      missingRequirements.push(check.label);
    }
  }

  const byType = new Map<string, Record<string, unknown>>();
  for (const document of documents) {
    const type = typeof document.document_type === "string" ? document.document_type : "";
    if (type) {
      byType.set(type, document);
    }
  }

  for (const type of REQUIRED_DRIVER_DOCUMENT_TYPES) {
    const document = byType.get(type);
    if (document && typeof document.file_path === "string" && document.file_path.trim().length > 0) {
      completedCount += 1;
    } else {
      missingRequirements.push(driverDocumentLabel(type));
    }
  }

  const requiredCount = 4 + vehicleChecks.length + REQUIRED_DRIVER_DOCUMENT_TYPES.length;
  const progressPercent = Math.max(0, Math.min(100, Math.round((completedCount / requiredCount) * 100)));

  return {
    ok: true,
    profile,
    driverProfile,
    vehicle,
    documents,
    digitalPaymentPolicy,
    checklist: {
      requiredCount,
      completedCount,
      progressPercent,
      missingRequirements,
      canSubmit: missingRequirements.length === 0,
    },
  };
}

export function driverDocumentLabel(type: string): string {
  switch (type) {
    case "bi_front":
      return "BI frente";
    case "bi_back":
      return "BI verso";
    case "selfie":
      return "Selfie";
    case "driver_license":
      return "Carta de conducao";
    case "vehicle_registration":
      return "Livrete";
    case "vehicle_front":
      return "Foto do carro frente";
    case "vehicle_back":
      return "Foto do carro traseira";
    case "vehicle_side":
      return "Foto do carro lateral";
    case "vehicle_interior":
      return "Foto do carro interior";
    case "vehicle_with_driver":
      return "Foto do carro com motorista";
    default:
      return type.replaceAll("_", " ");
  }
}

