import { supabaseAdmin } from "./supabase-admin.ts";

const COOLDOWN_THRESHOLD_7D = 3;
const COOLDOWN_WINDOW_DAYS = 7;
const COOLDOWN_HOURS = 24;
const SUSPENSION_THRESHOLD_14D = 5;
const SUSPENSION_WINDOW_DAYS = 14;

export type DriverDigitalPaymentPolicy = {
  mode: "enabled" | "cooldown" | "suspended";
  digitalTripsEnabled: boolean;
  recentRefusals7d: number;
  recentRefusals14d: number;
  lastRefusalAt: string | null;
  cooldownUntil: string | null;
  suspensionRecommended: boolean;
};

export function isDigitalPaymentMethod(paymentMethod: string | null | undefined): boolean {
  return paymentMethod === "mpesa" || paymentMethod === "emola";
}

export async function loadDriverDigitalPaymentPolicy(
  driverUserId: string,
): Promise<DriverDigitalPaymentPolicy> {
  const now = new Date();
  const sevenDaysAgo = new Date(now.getTime() - (COOLDOWN_WINDOW_DAYS * 24 * 60 * 60 * 1000));
  const fourteenDaysAgo = new Date(now.getTime() - (SUSPENSION_WINDOW_DAYS * 24 * 60 * 60 * 1000));

  const { data: refusalEvents, error } = await supabaseAdmin
    .from("trip_events")
    .select("created_at")
    .eq("actor_user_id", driverUserId)
    .eq("event_type", "driver_digital_payment_refused")
    .gte("created_at", fourteenDaysAgo.toISOString())
    .order("created_at", { ascending: false });

  if (error) {
    throw error;
  }

  const recentEvents = refusalEvents ?? [];
  const lastRefusalAt = recentEvents[0]?.created_at?.toString?.() ?? null;
  let recentRefusals7d = 0;

  for (const event of recentEvents) {
    const createdAt = new Date(event.created_at);
    if (!Number.isNaN(createdAt.getTime()) && createdAt >= sevenDaysAgo) {
      recentRefusals7d += 1;
    }
  }

  const recentRefusals14d = recentEvents.length;
  const suspensionRecommended = recentRefusals14d >= SUSPENSION_THRESHOLD_14D;

  let cooldownUntil: string | null = null;
  let mode: DriverDigitalPaymentPolicy["mode"] = "enabled";

  if (lastRefusalAt && recentRefusals7d >= COOLDOWN_THRESHOLD_7D) {
    const candidate = new Date(new Date(lastRefusalAt).getTime() + (COOLDOWN_HOURS * 60 * 60 * 1000));
    if (!Number.isNaN(candidate.getTime()) && candidate > now) {
      cooldownUntil = candidate.toISOString();
      mode = "cooldown";
    }
  }

  if (suspensionRecommended) {
    mode = "suspended";
    cooldownUntil = null;
  }

  return {
    mode,
    digitalTripsEnabled: mode === "enabled",
    recentRefusals7d,
    recentRefusals14d,
    lastRefusalAt,
    cooldownUntil,
    suspensionRecommended,
  };
}

export async function recordDriverDigitalPaymentRefusal(params: {
  tripId: string;
  driverUserId: string;
  paymentMethod: "mpesa" | "emola";
  cancellationReason?: string | null;
}) {
  const { error } = await supabaseAdmin
    .from("trip_events")
    .insert({
      trip_id: params.tripId,
      actor_user_id: params.driverUserId,
      event_type: "driver_digital_payment_refused",
      payload: {
        payment_method: params.paymentMethod,
        cancellation_reason: params.cancellationReason ?? null,
      },
    });

  if (error) {
    throw error;
  }
}

export async function suspendDriverForDigitalRefusals(params: {
  tripId: string;
  driverUserId: string;
  recentRefusals14d: number;
}) {
  const { error: updateError } = await supabaseAdmin
    .from("driver_profiles")
    .update({
      status: "suspended",
      is_online: false,
      rejection_reason: "Conta suspensa automaticamente por recusas repetidas de pagamentos digitais.",
    })
    .eq("user_id", params.driverUserId);

  if (updateError) {
    throw updateError;
  }

  const { error: eventError } = await supabaseAdmin
    .from("trip_events")
    .insert({
      trip_id: params.tripId,
      actor_user_id: params.driverUserId,
      event_type: "driver_digital_policy_suspended",
      payload: {
        recent_refusals_14d: params.recentRefusals14d,
        reason: "automatic_suspension_for_repeated_digital_refusals",
      },
    });

  if (eventError) {
    throw eventError;
  }
}

import { getRequestUser } from "./request-user.ts";
import { supabaseAdmin } from "./supabase-admin.ts";

export type RequestProfileContext = {
  userId: string;
  role: string;
  isActive: boolean;
  fullName: string | null;
  phoneE164: string | null;
};

export type RequestDriverContext = RequestProfileContext & {
  driverStatus: string;
  onboardingCompleted: boolean;
  isOnline: boolean;
  currentLat: number | null;
  currentLng: number | null;
};

export async function getRequestProfileContext(request: Request): Promise<RequestProfileContext | null> {
  const user = await getRequestUser(request);
  if (!user) {
    return null;
  }

  let { data: profile, error } = await supabaseAdmin
    .schema("public")
    .from("profiles")
    .select("id, user_id, role, full_name, phone")
    .eq("user_id", user.id)
    .maybeSingle();

  // Older SARCA rows used profiles.id as the auth id. Keep both layouts
  // readable while the production data is migrated incrementally.
  if (!profile && !error) {
    const fallback = await supabaseAdmin
      .schema("public")
      .from("profiles")
      .select("id, user_id, role, full_name, phone")
      .eq("id", user.id)
      .maybeSingle();
    profile = fallback.data;
    error = fallback.error;
  }

  if (error || !profile) {
    return null;
  }

  return {
    userId: profile.user_id ?? profile.id,
    role: profile.role,
    isActive: true,
    fullName: profile.full_name ?? null,
    phoneE164: profile.phone ?? null,
  };
}

export async function getRequestDriverContext(request: Request): Promise<RequestDriverContext | null> {
  const profile = await getRequestProfileContext(request);
  if (!profile || !profile.isActive) {
    return null;
  }

  const { data: centralRole, error: roleError } = await supabaseAdmin
    .schema("public")
    .from("user_roles")
    .select("role")
    .eq("user_id", profile.userId)
    .eq("role", "driver")
    .maybeSingle();

  // During the additive rollout, legacy driver accounts remain usable until their role is backfilled.
  if (roleError || (!centralRole && profile.role !== "courier")) {
    return null;
  }

  const { data: driverProfile, error } = await supabaseAdmin
    .schema("sarca")
    .from("driver_profiles")
    .select("status, onboarding_completed, is_online, current_lat, current_lng")
    .eq("user_id", profile.userId)
    .single();

  if (error || !driverProfile) {
    return null;
  }

  return {
    ...profile,
    driverStatus: driverProfile.status,
    onboardingCompleted: driverProfile.onboarding_completed === true,
    isOnline: driverProfile.is_online === true,
    currentLat: driverProfile.current_lat == null ? null : Number(driverProfile.current_lat),
    currentLng: driverProfile.current_lng == null ? null : Number(driverProfile.current_lng),
  };
}

import { createClient } from "jsr:@supabase/supabase-js@2";
import { runtimeEnv } from "./env.ts";

export async function getRequestUser(request: Request) {
  const authorization = request.headers.get("Authorization");

  if (!authorization?.startsWith("Bearer ")) {
    return null;
  }

  if (!runtimeEnv.supabaseAnonKey) {
    throw new Error("Missing required env var: SUPABASE_ANON_KEY");
  }

  const client = createClient(
    runtimeEnv.supabaseUrl,
    runtimeEnv.supabaseAnonKey,
    {
      db: {
        schema: "sarca",
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
      global: {
        headers: {
          Authorization: authorization,
        },
      },
    },
  );

  const { data, error } = await client.auth.getUser();
  if (error || !data.user) {
    return null;
  }

  return data.user;
}

export const corsHeaders: HeadersInit = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, PUT, PATCH, DELETE, OPTIONS",
};

export function jsonResponse(body: unknown, status = 200, headers: HeadersInit = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...corsHeaders,
      ...headers,
    },
  });
}

export function preflightResponse(): Response {
  return new Response("ok", {
    status: 200,
    headers: {
      ...corsHeaders,
    },
  });
}

export function methodNotAllowed(): Response {
  return jsonResponse({ error: "Method not allowed" }, 405);
}

export function badRequest(message: string): Response {
  return jsonResponse({ error: message }, 400);
}

export function internalError(message: string): Response {
  return jsonResponse({ error: message }, 500);
}
